package com.cafetecnologico.convertidor;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Lógica de audio y texto sin dependencias de Android.
 * Audio PCM de 16 bits: lectura de WAV, fundido de salida, silencio y unión de bloques.
 */
final class Audio {

    final byte[] pcm;
    final int hz;
    final int canales;

    Audio(byte[] pcm, int hz, int canales) {
        this.pcm = pcm;
        this.hz = hz;
        this.canales = canales;
    }

    // ---------- Lectura ----------

    static boolean esWav(byte[] d) {
        return d.length > 12 && d[0] == 'R' && d[1] == 'I' && d[2] == 'F' && d[3] == 'F'
                && d[8] == 'W' && d[9] == 'A' && d[10] == 'V' && d[11] == 'E';
    }

    /** Acepta un WAV completo o PCM sin cabecera (24 kHz, mono, 16 bits). */
    static Audio desdeBytes(byte[] datos) {
        if (datos == null || datos.length == 0) {
            throw new IllegalArgumentException("El audio llegó vacío.");
        }
        if (!esWav(datos)) {
            return new Audio(recortarPar(datos, 1), 24000, 1);
        }
        int hz = 24000, canales = 1, bits = 16;
        int ini = -1, fin = datos.length;
        ByteBuffer b = ByteBuffer.wrap(datos).order(ByteOrder.LITTLE_ENDIAN);
        long pos = 12;
        while (pos + 8 <= datos.length) {
            int p = (int) pos;
            String id = new String(datos, p, 4, StandardCharsets.US_ASCII);
            long tam = b.getInt(p + 4) & 0xFFFFFFFFL;
            if (id.equals("fmt ") && p + 8 + 16 <= datos.length) {
                canales = b.getShort(p + 10);
                hz = b.getInt(p + 12);
                bits = b.getShort(p + 22);
            } else if (id.equals("data")) {
                ini = p + 8;
                long f = ini + tam;
                boolean sinTamano = tam == 0 || tam == 0xFFFFFFFFL || f > datos.length;
                fin = sinTamano ? datos.length : (int) f;
                break;
            }
            pos = pos + 8 + tam + (tam & 1);
        }
        if (ini < 0) {
            ini = Math.min(44, datos.length);
            fin = datos.length;
        }
        if (bits != 16) {
            throw new IllegalArgumentException("Formato de audio no compatible: " + bits + " bits.");
        }
        if (canales < 1) canales = 1;
        if (hz < 8000) hz = 24000;
        byte[] pcm = new byte[fin - ini];
        System.arraycopy(datos, ini, pcm, 0, pcm.length);
        return new Audio(recortarPar(pcm, canales), hz, canales);
    }

    private static byte[] recortarPar(byte[] pcm, int canales) {
        int marco = 2 * canales;
        int largo = pcm.length - (pcm.length % marco);
        if (largo == pcm.length) return pcm;
        byte[] r = new byte[largo];
        System.arraycopy(pcm, 0, r, 0, largo);
        return r;
    }

    // ---------- Procesado ----------

    /** Fundido de salida tipo Hann sobre los últimos ms milisegundos. */
    static byte[] fundidoSalida(byte[] pcm, int hz, int canales, int ms) {
        byte[] r = pcm.clone();
        int marcos = r.length / (2 * canales);
        int n = Math.min(marcos, hz * ms / 1000);
        if (n < 2) return r;
        ByteBuffer b = ByteBuffer.wrap(r).order(ByteOrder.LITTLE_ENDIAN);
        for (int i = 0; i < n; i++) {
            double w = 0.5 * (1 + Math.cos(Math.PI * i / (n - 1)));
            int marco = marcos - n + i;
            for (int c = 0; c < canales; c++) {
                int idx = (marco * canales + c) * 2;
                b.putShort(idx, (short) Math.round(b.getShort(idx) * w));
            }
        }
        return r;
    }

    static byte[] silencio(int hz, int canales, int ms) {
        return new byte[(hz * ms / 1000) * canales * 2];
    }

    /**
     * Une los bloques: fundido de 50 ms al final de cada uno, pausa entre bloques
     * y silencio final. Devuelve un WAV completo.
     */
    static byte[] unir(List<Audio> bloques, int pausaMs, int silencioFinalMs) {
        if (bloques.isEmpty()) throw new IllegalArgumentException("No hay audio que unir.");
        int hz = bloques.get(0).hz;
        int canales = bloques.get(0).canales;
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = 0; i < bloques.size(); i++) {
            Audio a = bloques.get(i);
            if (a.hz != hz || a.canales != canales) {
                throw new IllegalArgumentException("Los bloques de audio no coinciden en formato.");
            }
            byte[] f = fundidoSalida(a.pcm, hz, canales, 50);
            out.write(f, 0, f.length);
            if (i < bloques.size() - 1 && pausaMs > 0) {
                byte[] s = silencio(hz, canales, pausaMs);
                out.write(s, 0, s.length);
            }
        }
        byte[] fin = silencio(hz, canales, silencioFinalMs);
        out.write(fin, 0, fin.length);
        return aWav(out.toByteArray(), hz, canales);
    }

    static byte[] aWav(byte[] pcm, int hz, int canales) {
        int bits = 16;
        ByteBuffer bb = ByteBuffer.allocate(44 + pcm.length).order(ByteOrder.LITTLE_ENDIAN);
        bb.put("RIFF".getBytes(StandardCharsets.US_ASCII));
        bb.putInt(36 + pcm.length);
        bb.put("WAVE".getBytes(StandardCharsets.US_ASCII));
        bb.put("fmt ".getBytes(StandardCharsets.US_ASCII));
        bb.putInt(16);
        bb.putShort((short) 1);
        bb.putShort((short) canales);
        bb.putInt(hz);
        bb.putInt(hz * canales * bits / 8);
        bb.putShort((short) (canales * bits / 8));
        bb.putShort((short) bits);
        bb.put("data".getBytes(StandardCharsets.US_ASCII));
        bb.putInt(pcm.length);
        bb.put(pcm);
        return bb.array();
    }

    // ---------- Texto ----------

    static int bytesUtf8(String s) {
        int n = 0;
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            n += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
            i += Character.charCount(cp);
        }
        return n;
    }

    /** Parte el texto en bloques de como máximo maxBytes bytes UTF-8, cortando en frases si puede. */
    static List<String> dividir(String texto, int maxBytes) {
        List<String> r = new ArrayList<>();
        String resto = texto == null ? "" : texto.trim();
        while (!resto.isEmpty()) {
            if (bytesUtf8(resto) <= maxBytes) {
                r.add(resto);
                break;
            }
            int limite = 0, acumulado = 0;
            while (limite < resto.length()) {
                int cp = resto.codePointAt(limite);
                int tam = cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
                if (acumulado + tam > maxBytes) break;
                acumulado += tam;
                limite += Character.charCount(cp);
            }
            if (limite <= 0) limite = Math.min(resto.length(), 1);
            int minimo = limite / 3;
            int corte = -1;
            for (int i = limite - 1; i >= minimo; i--) {
                char c = resto.charAt(i);
                if (c == '\n') { corte = i + 1; break; }
                if ((c == '.' || c == '!' || c == '?' || c == '…')
                        && (i + 1 >= limite || Character.isWhitespace(resto.charAt(i + 1)))) {
                    corte = i + 1;
                    break;
                }
            }
            if (corte < 0) {
                for (int i = limite - 1; i >= minimo; i--) {
                    if (Character.isWhitespace(resto.charAt(i))) { corte = i + 1; break; }
                }
            }
            if (corte < 0) corte = limite;
            String trozo = resto.substring(0, corte).trim();
            if (!trozo.isEmpty()) r.add(trozo);
            resto = resto.substring(corte).trim();
        }
        return r;
    }

    /** Quita lo que Android no admite en nombres de archivo. Devuelve "" si no queda nada. */
    static String nombreSeguro(String entrada) {
        String s = entrada == null ? "" : entrada.trim();
        String bajo = s.toLowerCase(Locale.ROOT);
        if (bajo.endsWith(".wav") || bajo.endsWith(".m4a") || bajo.endsWith(".mp3")) {
            s = s.substring(0, s.length() - 4);
        }
        s = s.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]", "");
        s = s.replaceAll("\\s+", " ").trim();
        while (s.startsWith(".") || s.endsWith(".")) {
            if (s.startsWith(".")) s = s.substring(1).trim();
            if (s.endsWith(".")) s = s.substring(0, s.length() - 1).trim();
        }
        if (s.length() > 100) s = s.substring(0, 100).trim();
        return s;
    }

    // ---------- Conversación con dos voces ----------

    /**
     * Conversación entre dos personas. El texto escribe cada intervención en una línea que
     * empieza con "Nombre:" y debe haber exactamente dos nombres distintos. Los nombres reales
     * no se leen: a Google se le mandan como "Locutor 1" y "Locutor 2".
     */
    static final class Conversacion {

        static final String[] IDS = {"Locutor 1", "Locutor 2"};

        static final String[] FEMENINAS = {
            "Kore", "Zephyr", "Leda", "Aoede", "Callirrhoe", "Autonoe", "Despina", "Erinome",
            "Laomedeia", "Achernar", "Gacrux", "Pulcherrima", "Vindemiatrix", "Sulafat"
        };

        private static final Pattern LINEA =
                Pattern.compile("^\\s*([\\p{L}\\p{N}][\\p{L}\\p{N} .'\\-]*):(.*)$");

        /** Una intervención: h es 1 o 2 (primer o segundo nombre) y t su texto. */
        static final class Turno {
            final int h;
            String t;

            Turno(int h, String t) {
                this.h = h;
                this.t = t;
            }
        }

        final String[] nombres;
        final Map<String, Integer> claves;
        /** Voces de los dos hablantes; las llena quien convierte. */
        final String[] voces = new String[2];
        /** Quién hablaba al final del bloque anterior, por si un bloque empieza sin nombre. */
        int hablante = 1;

        private Conversacion(String[] nombres, Map<String, Integer> claves) {
            this.nombres = nombres;
            this.claves = claves;
        }

        static boolean esFemenina(String voz) {
            for (String f : FEMENINAS) {
                if (f.equals(voz)) return true;
            }
            return false;
        }

        /** Voz de distinto género que la primera. */
        static String vozAutomatica(String voz1) {
            return esFemenina(voz1) ? "Charon" : "Kore";
        }

        static String normalizar(String s) {
            String n = java.text.Normalizer.normalize(s.toLowerCase(Locale.ROOT),
                    java.text.Normalizer.Form.NFD);
            return n.replaceAll("\\p{M}", "").trim();
        }

        /** Si la línea empieza con "Nombre:" devuelve {nombre, resto de la línea}; si no, null. */
        static String[] nombreDeLinea(String linea) {
            Matcher m = LINEA.matcher(linea);
            if (!m.find()) return null;
            String resto = m.group(2);
            if (!resto.isEmpty() && !Character.isWhitespace(resto.charAt(0))) return null;
            String n = m.group(1).trim();
            if (n.isEmpty() || n.length() > 24) return null;
            boolean hayLetra = false;
            for (int i = 0; i < n.length(); i++) {
                if (Character.isLetter(n.charAt(i))) {
                    hayLetra = true;
                    break;
                }
            }
            if (!hayLetra) return null;
            if (n.split("\\s+").length > 3) return null;
            return new String[] {n, resto.trim()};
        }

        /** Devuelve la conversación si el texto empieza con "Nombre:" y tiene dos nombres; si no, null. */
        static Conversacion detectar(String texto) {
            String t = texto == null ? "" : texto.replace("\r", "");
            t = t.replaceAll("\\[[^\\]]*\\]", "").replaceAll("\\{[^}]*\\}", "");
            List<String> nombres = new ArrayList<>();
            Map<String, Integer> claves = new HashMap<>();
            int total = 0;
            boolean primero = true;
            for (String linea : t.split("\n", -1)) {
                if (linea.trim().isEmpty()) continue;
                String[] nl = nombreDeLinea(linea);
                if (primero && nl == null) return null;
                primero = false;
                if (nl != null) {
                    total++;
                    String k = normalizar(nl[0]);
                    if (!claves.containsKey(k)) {
                        if (nombres.size() >= 2) return null;
                        nombres.add(nl[0]);
                        claves.put(k, nombres.size());
                    }
                }
            }
            if (nombres.size() == 2 && total >= 2) {
                return new Conversacion(new String[] {nombres.get(0), nombres.get(1)}, claves);
            }
            return null;
        }

        /**
         * Parte un bloque de texto en intervenciones. Lo que no empieza con un nombre sigue con
         * el hablante anterior (el del final del bloque previo, si es la primera línea).
         */
        List<Turno> turnos(String texto) {
            List<Turno> turnos = new ArrayList<>();
            Turno actual = null;
            int h = hablante;
            for (String linea : texto.replace("\r", "").split("\n", -1)) {
                String[] nl = nombreDeLinea(linea);
                Integer k = nl == null ? null : claves.get(normalizar(nl[0]));
                if (k != null) {
                    h = k;
                    actual = new Turno(k, nl[1]);
                    turnos.add(actual);
                } else {
                    String l = linea.trim();
                    if (l.isEmpty()) continue;
                    if (actual == null) {
                        actual = new Turno(h, "");
                        turnos.add(actual);
                    }
                    actual.t = actual.t + (actual.t.isEmpty() ? "" : " ") + l;
                }
            }
            List<Turno> res = new ArrayList<>();
            for (Turno t : turnos) {
                t.t = t.t.trim();
                if (!t.t.isEmpty()) res.add(t);
            }
            return res;
        }

        /** Quién habla al terminar esas intervenciones. */
        int ultimoDe(List<Turno> turnos) {
            return turnos.isEmpty() ? hablante : turnos.get(turnos.size() - 1).h;
        }
    }

    // ---------- Biblioteca de voces (función experimental, versión 1.6.0) ----------

    /**
     * Voces regionales en español de la biblioteca extendida de Google. Aquí solo hay lógica sin
     * Android: etiquetas en español, filtros, guardado como texto y las decisiones de respaldo.
     */
    static final class Biblioteca {

        static final String[] GENEROS_TEXTO = {"Todos los géneros", "Mujer", "Hombre", "Neutra"};
        static final String[] GENEROS_CODIGO = {"", "female", "male", "neutral"};

        private static final String[][] ROLES = {
            {"advisor", "Asesor"},
            {"assistant", "Asistente"},
            {"commercial", "Comercial"},
            {"concierge", "Conserje"},
            {"csagent", "Atención al cliente"},
            {"podcaster", "Podcaster"},
            {"techagent", "Soporte técnico"},
            {"training", "Instructor"},
            {"tutor", "Tutor"},
        };

        static final class Voz {
            final String id;
            final String acento;
            final String genero;
            final String tono;
            final String persona;
            final String idioma;

            Voz(String id, String acento, String genero, String tono, String persona,
                String idioma) {
                this.id = limpiar(id);
                this.acento = limpiar(acento);
                this.genero = limpiar(genero).toLowerCase(Locale.ROOT);
                this.tono = limpiar(tono).toLowerCase(Locale.ROOT);
                this.persona = limpiar(persona);
                this.idioma = limpiar(idioma);
            }

            /** Descripción corta en español, para las listas y los avisos. */
            String etiqueta() {
                StringBuilder sb = new StringBuilder(rolDeId(id));
                String g = generoEs(genero);
                if (!g.isEmpty()) sb.append(", ").append(g);
                String t = tonoEs(tono);
                if (!t.isEmpty()) sb.append(", tono ").append(t);
                return sb.toString();
            }
        }

        /** Quita lo que rompe el guardado como texto: barras verticales y saltos de línea. */
        static String limpiar(String s) {
            if (s == null) return "";
            return s.replace('|', ' ').replace('\n', ' ').replace('\r', ' ').trim();
        }

        static String generoEs(String genero) {
            if ("female".equals(genero)) return "mujer";
            if ("male".equals(genero)) return "hombre";
            if ("neutral".equals(genero)) return "neutra";
            return "";
        }

        static String tonoEs(String tono) {
            if ("low".equals(tono)) return "grave";
            if ("medium".equals(tono)) return "medio";
            if ("high".equals(tono)) return "agudo";
            return "";
        }

        /** Nombre del acento en español. Los que no conocemos se muestran como los da Google. */
        static String nombreAcento(String acento) {
            String a = acento == null ? "" : acento.toLowerCase(Locale.ROOT);
            if (a.isEmpty()) return "Sin acento indicado";
            if (a.contains("mexic")) return "México";
            if (a.contains("argentin")) return "Argentina";
            if (a.contains("castil") || a.contains("castel") || a.contains("spain")
                    || a.equals("es")) return "España, castellano";
            if (a.equals("mx")) return "México";
            if (a.equals("ar")) return "Argentina";
            return acento;
        }

        /** Verdadero si la voz es de español: idioma es, es-419, es-ES... */
        static boolean esEspanol(String idioma, String id) {
            String l = idioma == null ? "" : idioma.toLowerCase(Locale.ROOT).replace('_', '-');
            if (l.equals("es") || l.startsWith("es-")) return true;
            String i = id == null ? "" : id.toLowerCase(Locale.ROOT);
            return l.isEmpty() && i.startsWith("es-");
        }

        /** De es-419-techagent-7 saca "Soporte técnico 7". Si no reconoce el formato, devuelve el id. */
        static String rolDeId(String id) {
            String[] p = id.split("-");
            if (p.length < 3 || !p[p.length - 1].matches("\\d+")) return id;
            String clave = p[p.length - 2].toLowerCase(Locale.ROOT);
            String rol = null;
            for (String[] r : ROLES) {
                if (r[0].equals(clave)) rol = r[1];
            }
            if (rol == null) {
                rol = clave.isEmpty() ? id : Character.toUpperCase(clave.charAt(0)) + clave.substring(1);
            }
            return rol + " " + p[p.length - 1];
        }

        static int numeroDeId(String id) {
            String[] p = id.split("-");
            String n = p[p.length - 1];
            if (!n.matches("\\d{1,6}")) return 0;
            return Integer.parseInt(n);
        }

        private static int comparar(Voz a, Voz b) {
            int c = rolDeId(a.id).replaceAll("\\d+$", "").compareTo(rolDeId(b.id).replaceAll("\\d+$", ""));
            if (c != 0) return c;
            c = Integer.compare(numeroDeId(a.id), numeroDeId(b.id));
            if (c != 0) return c;
            return a.id.compareTo(b.id);
        }

        /** Voces con ese acento (vacío = todos) y ese género (vacío = todos), en orden estable. */
        static List<Voz> filtrar(List<Voz> todas, String acento, String genero) {
            List<Voz> r = new ArrayList<>();
            for (Voz v : todas) {
                if (!acento.isEmpty() && !v.acento.equals(acento)) continue;
                if (!genero.isEmpty() && !v.genero.equals(genero)) continue;
                r.add(v);
            }
            java.util.Collections.sort(r, (a, b) -> comparar(a, b));
            return r;
        }

        /** Opciones de la lista de regiones: cada una es {acento tal como lo da Google, texto}. */
        static List<String[]> regiones(List<Voz> todas) {
            List<String[]> r = new ArrayList<>();
            if (todas.isEmpty()) {
                r.add(new String[] {"", "Aún no hay voces cargadas"});
                return r;
            }
            Map<String, Integer> cuenta = new HashMap<>();
            for (Voz v : todas) {
                Integer n = cuenta.get(v.acento);
                cuenta.put(v.acento, n == null ? 1 : n + 1);
            }
            List<String> acentos = new ArrayList<>(cuenta.keySet());
            final Map<String, Integer> c = cuenta;
            java.util.Collections.sort(acentos, (a, b) -> {
                int d = c.get(b) - c.get(a);
                return d != 0 ? d : a.compareTo(b);
            });
            r.add(new String[] {"", "Todas las regiones, " + todas.size() + " voces"});
            for (String a : acentos) {
                int n = c.get(a);
                r.add(new String[] {a, nombreAcento(a) + ", " + n + (n == 1 ? " voz" : " voces")});
            }
            return r;
        }

        /** Voz de la biblioteca de distinto género y del mismo acento, o null si no hay. */
        static Voz automatica(List<Voz> todas, Voz v) {
            String buscado = "female".equals(v.genero) ? "male" : "female";
            for (Voz o : filtrar(todas, v.acento, buscado)) {
                if (!o.id.equals(v.id)) return o;
            }
            return null;
        }

        /** Guardado como texto: una voz por línea, con los campos separados por barras. */
        static String serializar(List<Voz> voces) {
            StringBuilder sb = new StringBuilder();
            for (Voz v : voces) {
                sb.append(v.id).append('|').append(v.acento).append('|').append(v.genero)
                        .append('|').append(v.tono).append('|').append(v.persona).append('|')
                        .append(v.idioma).append('\n');
            }
            return sb.toString();
        }

        static List<Voz> leer(String texto) {
            List<Voz> r = new ArrayList<>();
            if (texto == null) return r;
            for (String linea : texto.split("\n")) {
                String[] p = linea.split("\\|", -1);
                if (p.length < 6 || p[0].trim().isEmpty()) continue;
                r.add(new Voz(p[0], p[1], p[2], p[3], p[4], p[5]));
            }
            return r;
        }

        /**
         * Decide si un error de Google se debe a la voz (y entonces conviene volver a las 30 voces)
         * y no al límite de uso o a la conexión. codigo es el de Google, o -1 si no hay.
         */
        static boolean fallaPorVoz(int codigo, String mensaje) {
            if (codigo == 400 || codigo == 403 || codigo == 404) return true;
            if (codigo > 0) return false;
            String m = mensaje == null ? "" : mensaje;
            return m.startsWith("La primera forma de pedir el audio")
                    || m.startsWith("Google no aceptó la conversación");
        }
    }

    // ---------- Señales sonoras (las mismas del complemento, WAV de 16 kHz en base64) ----------

    static final class Sonidos {
        static final String INICIO = "";
        static final String CARGA = "";
        static final String EXITO = "";
        static final String AVISO = "";
    }
}
